// Select Pending — status-driven idempotency + per-run cap + model allowlist. No web fetch.
const APPROVED_MODELS = ["gpt-4o-mini", "gpt-4.1-mini"];
const DEFAULT_MODEL = "gpt-4o-mini";
const HARD_CAP = 100;
const DEFAULT_CAP = 25;

const cfg = $('⭐ Configure Your Run').first().json;
let model = String(cfg.openai_model || '').trim();
if (!APPROVED_MODELS.includes(model)) model = DEFAULT_MODEL;

let cap = Number(cfg.max_per_run);
if (!Number.isFinite(cap) || cap <= 0) cap = DEFAULT_CAP;
cap = Math.min(Math.floor(cap), HARD_CAP);

const icp = String(cfg.icp_description || '').trim();

// Validate min_qualified_score HERE, before any billable call: a typo like 750 must be a clear
// config error up front, not a silent empty hand-off after every lead has been charged.
const minqRaw = String(cfg.min_qualified_score ?? '').trim();
const minq = minqRaw === '' ? 0 : Number(minqRaw);
if (!Number.isFinite(minq) || minq < 0 || minq > 100) {
  throw new Error("Configuration error: min_qualified_score must be a number between 0 and 100 " +
                  "(scores are 0-100). Got: '" + minqRaw + "'. Fix it in ⭐ Configure Your Run.");
}

const rows = $input.all();
const out = [];
for (const item of rows) {
  const j = item.json;
  const name    = String(j.name    || '').trim();
  const company = String(j.company || '').trim();
  const role    = String(j.role    || '').trim();
  const website = String(j.website || '').trim();
  const notes   = String(j.notes   || '').trim();
  const hasContent = name || company || website;                        // skip genuinely empty rows
  const done = String(j.status || '').trim().toLowerCase() === 'done';  // status-driven: clear 'status' to re-score
  if (!hasContent || done) continue;                                    // 'failed'/blank rows are (re)processed
  out.push({ json: {
    row_number: j.row_number,                                           // stable per-row match key
    name, company, role, website, notes,
    _model: model,
    _icp: icp,
  }});
  if (out.length >= cap) break;
}
return out;

// Build Scoring Prompt — compose the ICP + one lead into a strict scoring request.
const SYSTEM_RULES = "You are a B2B lead-qualification assistant. Given an Ideal Customer Profile (ICP) and ONE lead's details, assess how well the lead fits the ICP and produce an actionable, honest evaluation. (1) Use ONLY the ICP and the lead fields provided \u2014 NEVER invent facts about the lead (no assumed company size, funding, location, tech stack, intent, or names not present in the input). If a detail is missing, treat it as unknown and LOWER both the score band and the confidence rather than guessing. (2) NEVER MERGE SEPARATE FACTS INTO ONE CLAIM. Base red_flags, next_action and personalization_angle only on what the input actually says. (3) SCORE = integer 0-100 for fit to the ICP. Apply this rubric CONSISTENTLY; the band is set by how completely the lead meets the ICP and how material any caveat is: 90-100 = exceptional, near-exact fit meeting the ICP's core criteria with NO material caveat; 75-89 = strong fit with only a MINOR caveat or one small unknown; 55-74 = good but CAVEATED fit \u2014 meets some ICP criteria while a MATERIAL caveat or key unknown (relies partly on a marketplace, unclear size, mixed business model) clearly holds it back; 35-54 = partial or uncertain fit \u2014 a few criteria met, several missing or unknown; 15-34 = weak fit, mostly misaligned with the ICP; 0-14 = clear non-fit or an explicit disqualifier (excluded industry/type, size far outside the range). A lead that plainly matches EVERY stated ICP criterion belongs in 90-100, not the 80s; a genuine caveat (e.g. sells partly via a marketplace) must drop it into the caveated band, not keep it near the top. (4) tier follows the band: 'hot' = 75-100, 'warm' = 35-74, 'cold' = 0-34. (5) reason = 1-2 plain sentences naming the specific ICP criteria the lead meets or misses, and the caveat that set the band. (6) next_action = ONE specific, practical next step GROUNDED in this lead's own evidence (their product, stage, channel, role or notes) \u2014 never generic filler such as 'reach out to discuss collaboration'. If the input is too sparse to be specific, state the exact information to gather first (e.g. 'confirm staff size and whether they sell on their own store before any outreach'). (7) personalization_angle = one specific, genuine hook drawn from the lead's own details (empty string if the input offers nothing genuine \u2014 never fabricate one). (8) red_flags = a short comma-separated list of concrete disqualifiers or risks from the input (empty string if none). confidence = 'high|medium|low' ('low' when fields are sparse or the fit is uncertain). (9) Plain spoken English, no marketing fluff, no emojis, no exclamation marks. (10) Return STRICT JSON only: {\"score\":0,\"tier\":\"hot|warm|cold\",\"reason\":\"...\",\"next_action\":\"...\",\"personalization_angle\":\"...\",\"red_flags\":\"...\",\"confidence\":\"high|medium|low\"}.";
const leads = $input.all();
const out = [];
for (let i = 0; i < leads.length; i++) {
  const lead = leads[i].json;
  const icp = String(lead._icp || '').trim();
  const leadFields = {
    name: lead.name || '', company: lead.company || '', role: lead.role || '',
    website: lead.website || '', notes: lead.notes || '',
  };
  const user = [
    'IDEAL CUSTOMER PROFILE (ICP):',
    icp || '(No ICP was provided. Score general B2B fit conservatively and set confidence to "low".)',
    'LEAD (use ONLY these fields — do not invent anything else):',
    JSON.stringify(leadFields),
    'Return the assessment as strict JSON only.',
  ].join('\n\n');
  out.push({ json: { ...lead,
    _oai_body: {
      model: lead._model,
      messages: [
        { role: 'system', content: SYSTEM_RULES },
        { role: 'user', content: user },
      ],
      response_format: { type: 'json_object' },
      max_tokens: 500,
      temperature: 0.2,
    }
  }});
}
return out;

// Parse Score — robust parse; honest fallback; status-driven, retryable. No fabricated scores.
const inputs = $input.all();
const prepared = $('Build Scoring Prompt').all();
if (inputs.length !== prepared.length) throw new Error('openai/prepare item count mismatch: ' + inputs.length + ' vs ' + prepared.length);
const clean = s => String(s == null ? '' : s).replace(/[\r\n]+/g, ' ').trim();
const out = [];
for (let i = 0; i < inputs.length; i++) {
  const j = inputs[i].json;
  const lead = prepared[i].json;
  let score = null, tier = '', reason = '', nextAction = '', angle = '', redFlags = '', confidence = 'low';
  const apiFailed = !!j.error || !j.choices;

  if (!apiFailed) {
    try {
      const p = JSON.parse(j.choices?.[0]?.message?.content || '');
      const n = Number(p.score);
      if (Number.isFinite(n)) score = Math.max(0, Math.min(100, Math.round(n)));
      tier       = clean(p.tier).toLowerCase();
      reason     = clean(p.reason);
      nextAction = clean(p.next_action);
      angle      = clean(p.personalization_angle);
      redFlags   = clean(p.red_flags);
      confidence = clean(p.confidence).toLowerCase();
    } catch (e) { /* fallback below */ }
  }
  // A real success needs a numeric score AND a reason. Otherwise keep the row RETRYABLE:
  // blank outputs + status='failed' so a re-run re-scores it. Never write a fake score.
  const failed = apiFailed || score === null || !reason;
  if (failed) {
    score = ''; tier = ''; reason = ''; nextAction = ''; angle = ''; redFlags = ''; confidence = 'low';
  } else {
    if (!['hot','warm','cold'].includes(tier)) tier = score >= 75 ? 'hot' : (score >= 35 ? 'warm' : 'cold');
    if (!['high','medium','low'].includes(confidence)) confidence = 'medium';
  }

  out.push({ json: {
    row_number: lead.row_number,               // match key — write to THIS exact row
    score: score,
    tier: tier,
    reason: reason,
    next_action: nextAction,
    personalization_angle: angle,
    red_flags: redFlags,
    confidence: confidence,
    status: failed ? 'failed' : 'done',
    scored_at: new Date().toISOString().slice(0, 16).replace('T', ' '),
  }});
}
return out;

// Qualified Leads — POST-SCORE qualification. Every pending lead has ALREADY been scored once above;
// this forwards only leads whose score is at/above the Minimum Qualified Score. It does NOT skip or
// cheapen scoring — it just re-joins lead identity so users can CHAIN further automation off this node
// (send to CRM, draft outreach, Slack, etc.).
const cfg = $('⭐ Configure Your Run').first().json;
let min = Number(cfg.min_qualified_score);
if (!Number.isFinite(min)) min = 0;
min = Math.max(0, Math.min(100, min));   // belt-and-braces: Select Pending already rejects out-of-range
const scored = $('Parse Score').all();
const leads = $('Build Scoring Prompt').all();
const out = [];
for (let i = 0; i < scored.length; i++) {
  const s = scored[i].json;
  const L = (leads[i] && leads[i].json) || {};
  const n = Number(s.score);
  if (s.status === 'done' && Number.isFinite(n) && n >= min) {
    out.push({ json: {
      row_number: s.row_number,
      name: L.name || '', company: L.company || '', role: L.role || '', website: L.website || '',
      score: n, tier: s.tier, reason: s.reason, next_action: s.next_action,
      personalization_angle: s.personalization_angle, red_flags: s.red_flags, confidence: s.confidence,
    }});
  }
}
return out;
